require __DIR__.'/bootstrap.php';require_auth();if(!can('payments.view')){http_response_code(403);exit('Forbidden');}require __DIR__.'/partials.php';$id=(int)($_GET['id']??$_POST['id']??0);$s=$db->prepare('SELECT * FROM customer_advances WHERE id=?');$s->execute([$id]);$advance=$s->fetch();if(!$advance){http_response_code(404);exit('Advance not found');}$applied=(float)$advance['amount']-(float)$advance['remaining_amount'];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$db->beginTransaction();try{$lock=$db->prepare('SELECT * FROM customer_advances WHERE id=? FOR UPDATE');$lock->execute([$id]);$old=$lock->fetch();if(!$old)throw new RuntimeException('Advance not found.');$alreadyApplied=(float)$old['amount']-(float)$old['remaining_amount'];$amount=max(0,(float)($_POST['amount']??0));if($amount<$alreadyApplied)throw new RuntimeException('Advance amount cannot be lower than the '.money($alreadyApplied).' already applied to invoices.');$customerId=(int)($_POST['customer_id']??0);$productId=(int)($_POST['product_id']??0)?:null;$qty=$productId?max(0,(float)($_POST['reserved_quantity']??0)):null;$price=$productId?max(0,(float)($_POST['expected_unit_price']??0)):null;$remaining=$amount-$alreadyApplied;$status=$remaining<=0?'applied':($alreadyApplied>0?'partially_applied':'open');$new=['customer_id'=>$customerId,'product_id'=>$productId,'reserved_quantity'=>$qty,'expected_unit_price'=>$price,'amount'=>$amount,'remaining_amount'=>$remaining,'method'=>$_POST['method'],'reference_no'=>trim($_POST['reference_no']??''),'notes'=>trim($_POST['notes']??''),'status'=>$status];$db->prepare('UPDATE customer_advances SET customer_id=?,product_id=?,reserved_quantity=?,expected_unit_price=?,amount=?,remaining_amount=?,method=?,reference_no=?,notes=?,status=? WHERE id=?')->execute([...array_values($new),$id]);audit($db,'correct','customer_advance',$id,$old,$new);$db->commit();flash('success','Advance corrected. Old and new values were saved in the audit log.');redirect('advance_receipt.php?id='.$id);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();flash('danger',$e->getMessage());redirect('advance_edit.php?id='.$id);}}
$customers=$db->query('SELECT id,name,phone FROM customers WHERE status="active" ORDER BY name')->fetchAll();$products=$db->query('SELECT id,item_code,name,current_stock,retail_price FROM products WHERE status="active" ORDER BY name')->fetchAll();page_start('Edit Advance '.$advance['advance_no'],'advances.php');?>
<div class="edit-advance-actions"><a class="btn secondary" href="advances.php">← Customer Advances</a><a class="btn secondary" href="advance_receipt.php?id=<?=$id?>">View Receipt</a></div><section class="panel edit-advance-panel"><span class="eyebrow">Correct advance record</span><h2><?=e($advance['advance_no'])?></h2><p class="plain-help">Already applied to invoices: <b><?=money($applied)?></b>. The corrected advance cannot be lower than this amount.</p><form method="post"><input type="hidden" name="_csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$id?>"><label>Customer<select name="customer_id" required><?php foreach($customers as $c):?><option value="<?=$c['id']?>" <?=(int)$advance['customer_id']===(int)$c['id']?'selected':''?>><?=e($c['name'].' · '.$c['phone'])?></option><?php endforeach;?></select></label><label>Reserved item<select name="product_id"><option value="">General advance / item not decided</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" data-price="<?=$p['retail_price']?>" <?=(int)$advance['product_id']===(int)$p['id']?'selected':''?>><?=e($p['item_code'].' - '.$p['name'].' · Stock '.$p['current_stock'])?></option><?php endforeach;?></select></label><div class="form-grid"><label>Reserved quantity<input type="number" name="reserved_quantity" min="0" step=".001" value="<?=e($advance['reserved_quantity'])?>"></label><label>Expected unit price<input type="number" name="expected_unit_price" min="0" step=".01" value="<?=e($advance['expected_unit_price'])?>"></label></div><label>Advance amount<input type="number" name="amount" min="<?=$applied?>" step=".01" value="<?=e($advance['amount'])?>" required></label><label>Received using<select name="method"><option value="cash" <?=$advance['method']==='cash'?'selected':''?>>Cash</option><option value="card" <?=$advance['method']==='card'?'selected':''?>>Card</option><option value="bank_transfer" <?=$advance['method']==='bank_transfer'?'selected':''?>>Bank transfer</option><option value="cheque" <?=$advance['method']==='cheque'?'selected':''?>>Cheque</option></select></label><label>Reference<input name="reference_no" value="<?=e($advance['reference_no'])?>"></label><label>Notes<textarea name="notes" rows="3"><?=e($advance['notes'])?></textarea></label><button class="btn primary wide">Save Corrections</button></form></section><style>.edit-advance-actions{display:flex;justify-content:space-between;margin-bottom:16px}.edit-advance-panel{max-width:680px;margin:auto}.edit-advance-panel label{display:block;margin:14px 0}</style><?php page_end();
